diff:
@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix stable_1: <https://w3id.org/intigraph/camayoc/core/ns#> .
@prefix stable_9: <https://w3id.org/intigraph/quipu/ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

stable_1:MemoryDirectiveShape a sh:NodeShape ;
    sh:message "A memory Directive needs --rule, --issued-by, --applies-to and --topic, each exactly once. Run the cy create tool with --help for each field." ;
    sh:or ( [ sh:not [ sh:or ( [ sh:class stable_1:Directive ] [ sh:class aegis:Directive ] ) ] ] [ sh:node stable_1:MemoryDirectiveBodyShape ] ) ;
    sh:targetSubjectsOf aegis:naturalKey,
        stable_1:naturalKey .

stable_1:MemoryDirectiveBodyShape a sh:NodeShape ;
    sh:and ( [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:appliesTo ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:appliesTo ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:rule ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:rule ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:topic ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:topic ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_9:issuedBy ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:issuedBy ] ] ) ] ) ;
    sh:property [ sh:description "Who issued the rule: a Person or agent entity (IRI or local name)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs who issued it (--issued-by), as an existing person or agent." ;
            sh:name "issuedBy" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path aegis:issuedBy ],
        [ sh:datatype xsd:string ;
            sh:description "The rule, as one imperative sentence." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs the rule as one imperative sentence (--rule)." ;
            sh:name "rule" ;
            sh:order 1 ;
            sh:path stable_1:rule ],
        [ sh:description "Who issued the rule: a Person or agent entity (IRI or local name)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs who issued it (--issued-by), as an existing person or agent." ;
            sh:name "issuedBy" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path stable_9:issuedBy ],
        [ sh:description "The registered memory topic the rule governs (cy topic add registers one)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs a registered topic (--topic)." ;
            sh:name "topic" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path aegis:topic ],
        [ sh:description "The registered memory topic the rule governs (cy topic add registers one)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs a registered topic (--topic)." ;
            sh:name "topic" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path stable_1:topic ],
        [ sh:description "Who or what the rule binds: an agent, CrewRole or repo, or 'crew' for everyone." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs who it applies to (--applies-to), an existing agent, role or repo, or 'crew'." ;
            sh:name "appliesTo" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path aegis:appliesTo ],
        [ sh:datatype xsd:string ;
            sh:description "The rule in the issuer's own words." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --verbatim quote." ;
            sh:name "verbatim" ;
            sh:order 7 ;
            sh:path stable_1:verbatim ],
        [ sh:datatype xsd:string ;
            sh:description "The rule, as one imperative sentence." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs the rule as one imperative sentence (--rule)." ;
            sh:name "rule" ;
            sh:order 1 ;
            sh:path aegis:rule ],
        [ sh:datatype xsd:string ;
            sh:description "Why the rule exists, in one sentence." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --why." ;
            sh:name "why" ;
            sh:order 6 ;
            sh:path aegis:why ],
        [ sh:datatype xsd:string ;
            sh:description "The rule in the issuer's own words." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --verbatim quote." ;
            sh:name "verbatim" ;
            sh:order 7 ;
            sh:path aegis:verbatim ],
        [ sh:description "Who or what the rule binds: an agent, CrewRole or repo, or 'crew' for everyone." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a directive needs who it applies to (--applies-to), an existing agent, role or repo, or 'crew'." ;
            sh:name "appliesTo" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path stable_1:appliesTo ],
        [ sh:datatype xsd:string ;
            sh:description "Why the rule exists, in one sentence." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --why." ;
            sh:name "why" ;
            sh:order 6 ;
            sh:path stable_1:why ],
        [ sh:datatype xsd:string ;
            sh:description "The date the rule was given, YYYY-MM-DD." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: --issued-on is one date, YYYY-MM-DD." ;
            sh:name "issuedOn" ;
            sh:order 5 ;
            sh:path stable_1:issuedOn ;
            sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ],
        [ sh:datatype xsd:string ;
            sh:description "The date the rule was given, YYYY-MM-DD." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: --issued-on is one date, YYYY-MM-DD." ;
            sh:name "issuedOn" ;
            sh:order 5 ;
            sh:path aegis:issuedOn ;
            sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ] .
